const fallback={schema_version:'1.0',snapshot_id:'demo',generated_at:null,data_status:'DEMO',agents:{},metrics:{},portfolios:[],alerts:[],decisions:[],orders:[],positions:[],quotas:[],diagnostics:[],work:{roadmap:[],commits:[]}};
let snapshot=fallback;let selectedAgent='stock';
const money=v=>v==null?'Indisponible':new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v);
const pct=v=>v==null?'Indisponible':`${v>0?'+':''}${v.toFixed(1)} %`;
const time=v=>v?new Date(v).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'}):'Indisponible';
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(text,kind='neutral')=>`<span class="pill ${kind}">${esc(text)}</span>`;
const agentKey=name=>name.toLowerCase().includes('crypto')?'crypto':'stock';
const agentName=key=>snapshot.agents[key]?.name||key;
const agentKpis=a=>a.kpis||{pnl_net:null,drawdown:null,portfolio_value:null,available_budget:null,committed_budget:null,ai_cost:null};
function kpi(label,value,reason,kind='') { return `<article class="metric ${kind}"><label>${esc(label)}</label><strong>${value}</strong><small>${esc(reason)}</small></article>`; }
function renderAgentCards(){
  document.querySelector('#agents').innerHTML=Object.entries(snapshot.agents).map(([key,a])=>{const k=agentKpis(a);return `<article class="agent-card selectable" data-agent-card="${key}"><span class="pill ${a.status==='RUNNING'?'live':'neutral'}">${esc(a.status)}</span><div class="agent-title"><span class="agent-mark">${key==='crypto'?'₿':'S'}</span><div><h3>${esc(a.name)}</h3><div class="muted">${esc(a.environment)} · ${esc(a.phase)}</div></div></div><div class="status">${a.status==='RUNNING'?'Opérationnel':a.status==='STALE'?'Périmé':'À synchroniser'}</div><div class="agent-meta"><div><span>Machine</span><b>${esc(a.machine)}</b></div><div><span>Dernier signal</span><b>${time(a.last_seen_at)}</b></div><div><span>Version</span><b>${esc(a.release)}</b></div><div><span>Santé</span><b>${esc(a.health)}</b></div></div><div class="agent-card-kpis"><div><span>PnL net</span><b class="${k.pnl_net>=0?'positive':'negative'}">${money(k.pnl_net)}</b></div><div><span>Drawdown</span><b class="negative">${pct(k.drawdown)}</b></div><div><span>Portefeuille</span><b>${money(k.portfolio_value)}</b></div><div><span>Disponible</span><b>${money(k.available_budget)}</b></div></div><button class="detail-button" data-agent-detail="${key}">Voir le détail ${key==='crypto'?'Crypto':'Stock'} →</button></article>`}).join('');
  document.querySelectorAll('[data-agent-detail],[data-agent-card]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();selectAgent(el.dataset.agentDetail||el.dataset.agentCard)}));
}
function renderOverview(){
  document.querySelector('#snapshot-time').textContent=time(snapshot.generated_at);renderAgentCards();
  document.querySelector('#portfolio-summary').innerHTML=snapshot.portfolios.map(p=>`<article class="mini-portfolio"><div class="portfolio-head"><h3>${esc(p.agent)}</h3>${badge(p.environment,'demo')}</div><div class="portfolio-total">${money(p.total_value)}</div><div class="muted">${esc(p.label)} · PnL ${pct(p.pnl_net)}</div><div class="bar"><i style="width:${Math.min(100,Math.max(0,p.committed/p.total_value*100))}%"></i></div><small>${money(p.committed)} engagé · ${money(p.available)} disponible</small></article>`).join('');
  document.querySelector('#alerts').innerHTML=snapshot.alerts.map(a=>`<div class="alert ${a.severity==='GUARDRAIL'?'guardrail':''}"><div>${badge(a.severity,a.severity==='GUARDRAIL'?'warn':'neutral')}<strong>${esc(a.title)}</strong></div><span>${esc(a.detail)}</span></div>`).join('');
}
function decisionTable(items){return `<table><thead><tr><th>Heure</th><th>Actif</th><th>Décision</th><th>Confiance</th><th>Justification</th></tr></thead><tbody>${items.map(d=>`<tr><td>${time(d.at)}</td><td><b>${esc(d.symbol)}</b><small>${esc(d.environment)}</small></td><td>${badge(d.decision,d.decision==='BUY'?'good':d.decision==='SELL'?'bad':'neutral')}</td><td>${esc(d.confidence)}</td><td>${esc(d.rationale)}</td></tr>`).join('')}</tbody></table>`}
function orderTable(items){return `<table><thead><tr><th>Ordre</th><th>Environnement</th><th>Quantité</th><th>Prix ordre</th><th>Exécution</th><th>Statut</th></tr></thead><tbody>${items.map(o=>`<tr><td><b>${esc(o.side)} ${esc(o.symbol)}</b><small>${esc(o.id)}</small></td><td>${badge(o.environment,'demo')}</td><td>${esc(o.quantity)}</td><td>${money(o.order_price)}</td><td>${o.executed_quantity?`${esc(o.executed_quantity)} à ${money(o.executed_price)}`:'Aucune'}</td><td>${badge(o.status,o.status==='FILLED'?'good':o.status==='PARTIAL'?'warn':'neutral')}</td></tr>`).join('')}</tbody></table>`}
function positionCards(items){return items.map(p=>`<article class="position-card"><div class="position-head"><div><h3>${esc(p.symbol)}</h3><span class="muted">${esc(p.environment)}</span></div>${badge(p.asset_type,'neutral')}</div><div class="position-value">${money(p.market_value)}</div><div class="position-gridline"><span>Quantité <b>${esc(p.quantity)}</b></span><span>PRU <b>${money(p.avg_price)}</b></span><span>Dernier <b>${money(p.last_price)}</b></span><span>PnL <b class="${p.pnl_net>=0?'positive':'negative'}">${money(p.pnl_net)}</b></span></div></article>`).join('')}
function selectAgent(key){selectedAgent=key;document.querySelectorAll('[data-agent-switch]').forEach(b=>b.classList.toggle('active',b.dataset.agentSwitch===key));renderDetail();document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.panel==='agent-detail'));document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id==='agent-detail'));}
function renderDetail(){
  const a=snapshot.agents[selectedAgent];if(!a)return;const k=agentKpis(a);const decisions=snapshot.decisions.filter(d=>agentKey(d.agent)===selectedAgent);const orders=snapshot.orders.filter(o=>agentKey(o.agent)===selectedAgent);const positions=snapshot.positions.filter(p=>agentKey(p.agent)===selectedAgent);
  document.querySelector('#detail-title').textContent=`${a.name} · détail`;document.querySelector('#detail-subtitle').textContent=`${a.environment} · ${a.phase} · toutes les valeurs ci-dessous appartiennent à cet agent`;
  document.querySelector('#detail-kpis').innerHTML=kpi('PnL net',money(k.pnl_net),'Simulation/Paper fictif',k.pnl_net>=0?'positive':'negative')+kpi('Drawdown',pct(k.drawdown),'Maximum sur 30 jours fictifs','negative')+kpi('Portefeuille',money(k.portfolio_value),'Valeur synthétique')+kpi('Budget disponible',money(k.available_budget),'Cash non engagé')+kpi('Budget engagé',money(k.committed_budget),'Positions ouvertes')+kpi('Coût OpenAI + JEV',money(k.ai_cost),'Ledger attribué à cet agent');
  document.querySelector('#detail-positions').innerHTML=positionCards(positions);document.querySelector('#detail-decisions').innerHTML=decisionTable(decisions);document.querySelector('#detail-orders').innerHTML=orderTable(orders);
}
function renderHealth(){document.querySelector('#health-cards').innerHTML=Object.values(snapshot.agents).map(a=>`<article><span class="machine-icon">${a.name.includes('Crypto')?'◈':'⌘'}</span><h3>${esc(a.machine)}</h3><p class="muted">${esc(a.name)} · CPU ${esc(a.cpu)} · mémoire ${esc(a.memory)}</p>${badge(a.health,a.status==='RUNNING'?'live':'neutral')}<p class="tiny">Disque libre : ${esc(a.disk_free)} · fraîcheur : ${esc(a.freshness)}</p></article>`).join('');document.querySelector('#quotas').innerHTML=snapshot.quotas.map(q=>`<article class="quota"><div class="quota-head"><b>${esc(q.name)}</b><span>${esc(q.used)} / ${esc(q.limit)} ${esc(q.unit)}</span></div><div class="bar"><i style="width:${Math.min(100,q.used/q.limit*100)}%"></i></div><small>${esc(q.note)}</small></article>`).join('');document.querySelector('#diagnostics').innerHTML=snapshot.diagnostics.map(d=>`<div class="diagnostic"><span class="dot ${d.status==='OK'?'ok':d.status==='WARN'?'warn':'bad'}"></span><div><b>${esc(d.name)}</b><span>${esc(d.detail)}</span></div>${badge(d.status,d.status==='OK'?'good':d.status==='WARN'?'warn':'neutral')}</div>`).join('')}
function renderActivity(){for(const key of ['stock','crypto']){const decisions=snapshot.decisions.filter(d=>agentKey(d.agent)===key);const orders=snapshot.orders.filter(o=>agentKey(o.agent)===key);document.querySelector(`#${key}-activity`).innerHTML=`<div class="activity-block"><h4>Décisions</h4>${decisionTable(decisions)}</div><div class="activity-block"><h4>Ordres &amp; exécutions</h4>${orderTable(orders)}</div>`}}
function renderWork(){const roadmap=snapshot.work?.roadmap||[];const commits=snapshot.work?.commits||[];document.querySelector('#roadmap').innerHTML=roadmap.map((r,i)=>{const item=typeof r==='string'?{title:r,detail:'',status:'OPEN'}:r;return `<div class="roadmap-item"><span class="step">${i+1}</span><div><b>${esc(item.title)}</b><span>${esc(item.detail)}</span></div>${badge(item.status,item.status==='DONE'?'good':item.status==='NEXT'?'demo':'neutral')}</div>`}).join('');document.querySelector('#commits').innerHTML=commits.map(c=>`<div class="commit"><code>${esc(c.sha)}</code><div><b>${esc(c.title)}</b><span>${esc(c.scope)} · ${esc(c.when)}</span></div></div>`).join('')}
function render(data){snapshot=data;renderOverview();renderHealth();renderActivity();renderWork();renderDetail();}
function renderDataMode(data){const live=data.data_status&&data.data_status!=='DEMO';document.querySelector('#data-mode').textContent=live?data.data_status.replaceAll('_',' '):'MODE DÉMONSTRATION';document.querySelector('#data-notice').textContent=live?(data.notice||'Lecture seule · données issues des exporteurs locaux'):'Tout ce qui est affiché est fictif mais représentatif. Aucun chiffre ne vient d’un runtime réel.';}
const loadSnapshot=()=>fetch('snapshot.json',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject()).catch(()=>fetch('demo-snapshot.json',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject())).catch(()=>fallback);
loadSnapshot().then(data=>{renderDataMode(data);render(data);});
document.querySelectorAll('.tabs button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tabs button,.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.panel).classList.add('active')}));
document.querySelectorAll('[data-agent-switch]').forEach(b=>b.addEventListener('click',()=>selectAgent(b.dataset.agentSwitch)));
